const CONCEPTS=[
 ['Collection','Receiving money from an external party. Money flows into the company.','in'],
 ['Payment / Refund','Paying money to an external party. Money flows out. The menu calls all payments "Refund".','out'],
 ['Receivable (AR)','Amount an external party owes the company, for example premium due. ArapCate = 1.','in'],
 ['Payable (AP)','Amount the company owes an external party, for example a refund or a claim. ArapCate = 2.','out'],
 ['Suspense account','Temporary holding account for money received before it is matched to an AR.','in'],
 ['Offset / Application','Matching money or an opposite balance against an AR or AP so the balance becomes 0.','int'],
 ['Reversal','Undoing a completed step to restore the previous state. Can be redone.','out'],
 ['Cancel','Closing an outstanding AR, AP, commission or prepay order. Irreversible.','cancel'],
 ['Installment','An AR split into periodic payments. Each period is its own AR.',''],
 ['Settlement (commission)','Periodic process that turns commission fees into one AP or AR per producer.',''],
 ['Fee','Detailed record of each money movement, used for GL posting.',''],
 ['Statement','Groups many AR and AP of one party (producer or coinsurer) so they can be settled as one net amount.','int']
];
